#!/usr/bin/env bash
# analysis-route AC 2 (A1300 E13): every request without requested.route resolves exactly as at f9066716. The FFDR generator
# (unchanged) on the vendored f9066716 resolver and policy reproduces the checked-in base table byte for byte; on the tree under test it
# gives the same table row for row; the policy minus R3's additions equals f9066716's as a JSON value; tests/ffdr-route-table.test.sh and
# its fixture are f9066716's bytes and pass. From R (AR_ROOT): policy and resolver. Run alone: bash tests/analysis-route_ac02_base_table.test.sh
. "$(dirname "$0")/analysis-route_lib.sh"
GEN="$D/tests/fixtures/ffdr/gen-route-table.py"; BT="$AF/base-route-table.json"
POL="$R/.config/skill-routing/policy.json"; RES="$R/.local/lib/skill-route-resolve.py"
B=f9066716b260e6ba14b8a7cca8ee27b35954555d

ck "vendored f9066716 resolver, policy and gate present with their full sha256 digests (missing or changed = FAIL)" 'ar_fixtures_ok'
ck "base table: source f9066716, the vendored digests, 61 rows" 'jq -e --arg s "j0yen/dotfiles $B" --arg p "$AR_SHA_POL" --arg r "$AR_SHA_RES" ".source==\$s and .policy_sha256==\$p and .resolver_sha256==\$r and .row_count==(.table|length) and .row_count==61" "$BT" >/dev/null 2>&1'
python3 -I "$GEN" --policy "$BPOL" --resolver "$BRES" --source "j0yen/dotfiles $B" >"$T/regen.json" 2>"$T/regen.err"
ck "base table is byte-identical to a fresh generation from the vendored f9066716 bytes (never hand-edited)" 'cmp -s "$T/regen.json" "$BT"'
ck "base table covers every governed skill's baseline, classes, escalations and review reasons, and the max exception with a ledger record" 'jq -e "[.table[].id] as \$i | ([\"5whysandrhyme\",\"dream\",\"maxspeed\",\"wwhtbt\"] | all(. as \$s | \$i | index(\"\(\$s)|baseline\"))) and (\$i|index(\"dream|class:max_exception\")) and ([.table[]|select(.id==\"dream|class:max_exception\")][0] | .rc==0 and .request.exception.evidence==[\"ledger:A1300\"]) and ([\$i[]|select(test(\"\\\\|review:\"))]|length)==24" "$BT" >/dev/null 2>&1'
ck "FFDR generator, fixture, README and tests/ffdr-route-table.test.sh are byte-for-byte f9066716's (unmodified)" 'ar_sha "$GEN" 56febde5e52ce0a40ae61d0109af5242e005bb4acee787aabc24b60a1376415b && ar_sha "$D/tests/fixtures/ffdr/base-route-table.json" 11ca5cf221dab28d0acee56f83ca843bd34e59b294b62135c7e03f37b0e53a90 && ar_sha "$D/tests/fixtures/ffdr/README.md" 8654db8b84e0e7fc92170aba7335e69a85a54ddcd214ad8cdc06b12c5f8438c6 && ar_sha "$D/tests/ffdr-route-table.test.sh" c50a590e90656367c16db4fddabd2c388b090ae1cc3393d84376f1123da32cfd'

python3 -I "$GEN" --policy "$POL" --resolver "$RES" --source head >"$T/head.json" 2>"$T/head.err"; grc=$?
ck "head table generated by the same generator from the tree under test" '[ $grc = 0 ] && jq -e ".table|length>0" "$T/head.json" >/dev/null 2>&1'
python3 -I - "$BT" "$T/head.json" >"$T/cmp.txt" 2>&1 <<'PY'
import json, sys
b = json.load(open(sys.argv[1]))["table"]; h = json.load(open(sys.argv[2]))["table"]
print("count", len(b), len(h))
hb = {r["id"]: r for r in h}
bad = [r["id"] for r in b if hb.get(r["id"]) != r] + [i for i in hb if i not in {r["id"] for r in b}]
print("ids_order_equal", [r["id"] for r in b] == [r["id"] for r in h])
print("bad", len(bad))
for i in bad[:20]:
    print("MISMATCH", i, json.dumps(hb.get(i, {}).get("out"), sort_keys=True)[:300])
PY
ck "head table equals the f9066716 table row for row: same ids in the same order, same request, exit code and output on all 61 rows" 'grep -qx "count 61 61" "$T/cmp.txt" && grep -qx "ids_order_equal True" "$T/cmp.txt" && grep -qx "bad 0" "$T/cmp.txt" && jq -e --slurpfile b "$BT" ".table == \$b[0].table" "$T/head.json" >/dev/null 2>&1'
grep '^MISMATCH' "$T/cmp.txt" | head -10

R3DEL='del(.skills.wwhtbt.routes["opus-high"], .skills.wwhtbt.routes["opus-xhigh"], .skills.wwhtbt.alternates, .skills["5whysandrhyme"].routes["opus-high"], .skills["5whysandrhyme"].routes["opus-xhigh"], .skills["5whysandrhyme"].alternates)'
ck "the head policy minus R3's two routes and alternates per skill equals f9066716's policy as a JSON value" '[ -n "$(jq -c . "$POL" 2>/dev/null)" ] && [ "$(jq -S -c "$R3DEL" "$POL" 2>/dev/null)" = "$(jq -S -c . "$BPOL")" ]'
ck "R3 present, so the subtraction is not vacuous: both skills carry opus-high (claude-opus-5-5 high), opus-xhigh (claude-opus-5-5 xhigh) and alternates {fable-high:[opus-high], fable-xhigh:[opus-xhigh]}" 'jq -e -n --slurpfile p "$POL" "[\"wwhtbt\",\"5whysandrhyme\"] | all(. as \$s | \$p[0].skills[\$s] | .routes[\"opus-high\"]=={\"model\":\"claude-opus-5-5\",\"effort\":\"high\"} and .routes[\"opus-xhigh\"]=={\"model\":\"claude-opus-5-5\",\"effort\":\"xhigh\"} and .alternates=={\"fable-high\":[\"opus-high\"],\"fable-xhigh\":[\"opus-xhigh\"]})" >/dev/null 2>&1'
ck "approved is f9066716's text (not changed by this PRD)" '[ "$(jq -r .approved "$POL" 2>/dev/null)" = "$(jq -r .approved "$BPOL")" ]'
ck "no other skill carries alternates (dream, maxspeed unchanged)" 'jq -e "[.skills|to_entries[]|select(.value|has(\"alternates\"))|.key]|sort==[\"5whysandrhyme\",\"wwhtbt\"]" "$POL" >/dev/null 2>&1'
ck "the policy keeps its jq . layout" 'jq . "$POL" 2>/dev/null | cmp -s - "$POL"'

FFDR_ROOT="$R" bash "$D/tests/ffdr-route-table.test.sh" >"$T/ffdr.log" 2>&1; frc=$?
ck "tests/ffdr-route-table.test.sh, unmodified, passes on the tree under test" '[ $frc = 0 ] && grep -qx "ALL PASS" "$T/ffdr.log"' || grep FAIL "$T/ffdr.log" | head -5
ar_end
